def preserve_legacy_requests(apps, schema_editor):
    Request = apps.get_model("article", "RequestArticleChange")
    Article = apps.get_model("article", "Article")
    alias = schema_editor.connection.alias
    requests = Request.objects.using(alias)
    requests.update(status="completed", was_public=False)
    Package = apps.get_model("upload", "Package")
    Page = apps.get_model("article", "ArticleWebPage")
    for article in (
        Article.objects.using(alias)
        .filter(status__in=("required-update", "required-erratum"))
        .iterator()
    ):
        public = (
            Package.objects.using(alias)
            .filter(article_id=article.pk, public_ws_status="published")
            .exists()
            or Page.objects.using(alias)
            .filter(
                article_id=article.pk,
                purpose__in=("PUBLIC", "CLASSIC"),
                status__in=("available", "valid_content", "content_mismatch"),
            )
            .exists()
        )
        if not public and article.sps_pkg_id and article.sps_pkg.origin == "MIGRATION":
            value = article.first_pubdate_iso
            try:
                published = (
                    date.fromisoformat(value[:10])
                    if value
                    else article.first_publication_date
                )
                public = bool(
                    published and published <= datetime.now(timezone.utc).date()
                )
            except (ValueError, TypeError):
                public = False
        if not public:
            continue
        kind = "update" if article.status == "required-update" else "erratum"
        latest = (
            requests.filter(article_id=article.pk, change_type=kind)
            .order_by("-created", "-pk")
            .first()
        )
        if latest is not None and latest.comment and latest.comment.strip():
            requests.filter(pk=latest.pk).update(status="pending", was_public=True)


def grant_editorial_requests(apps, schema_editor):
    alias = schema_editor.connection.alias
    ContentType = apps.get_model("contenttypes", "ContentType")
    Permission = apps.get_model("auth", "Permission")
    Group = apps.get_model("auth", "Group")
    content_type, _ = ContentType.objects.using(alias).get_or_create(
        app_label="article", model="article"
    )
    permission, _ = Permission.objects.using(alias).get_or_create(
        content_type=content_type,
        codename="request_article_change",
        defaults={"name": "Can request article change"},
    )
    for group in Group.objects.using(alias).filter(
        name__in=(
            "COLLECTION_TEAM_ADMIN",
            "COLLECTION_TEAM_MEMBER",
            "JOURNAL_TEAM_ADMIN",
            "JOURNAL_TEAM_MEMBER",
        )
    ):
        group.permissions.add(permission)


